const leadId=$('Resolve Lead Id').first().json.lead_id;
if(!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(leadId))throw Error('Invalid lead ID');
const out=$json.output??$json, lead=$('Load Lead').first().json, context=$('Build research context').first().json;
const available=context.sources??[]; const citations=[];
for(const source of (Array.isArray(out.sources)?out.sources:[]).slice(0,10)){
 const reference=available.find(r=>r.url===source.url); const excerpt=String(source.excerpt??'').trim(); const claim=String(source.claim??'').trim();
 if(reference&&excerpt.length>=20&&reference.excerpt.includes(excerpt)&&claim.length>=4)citations.push({url:reference.url,title:reference.title,retrieved_at:reference.retrieved_at,claim,excerpt});
}
const claimed=(value)=>citations.some(c=>c.claim.toLowerCase()===String(value).toLowerCase());
const sector=typeof out.sector==='string'&&claimed(out.sector)?out.sector:null;
const past_projects=(Array.isArray(out.past_projects)?out.past_projects:[]).filter(claimed);
const partners=(Array.isArray(out.partners)?out.partners:[]).filter(claimed);
const needs=Array.isArray(lead.raw_payload?.requirements)?lead.raw_payload.requirements:[];
const warnings=[context.search_warning].filter(Boolean);
if((out.past_projects?.length??0)>past_projects.length||(out.partners?.length??0)>partners.length)warnings.push('Unsupported external claims omitted');
const prospect={lead_id:leadId,sector,revenue_estimate:null,past_projects,partners,domain_needs:needs,partial:true,warnings,raw:{organisation:lead.raw_payload?.organization??null,sources:citations}};
return [{json:{prospect_json:JSON.stringify(prospect)}}];

