const lead=$('Load Lead').first().json; const response=$json;
const org=String(lead.raw_payload?.organization??'').trim().toLowerCase();
const isPublic=(url)=>{try{const u=new URL(url);const h=u.hostname.toLowerCase();return u.protocol==='https:'&&!/^(localhost|.*\.local|127\.|10\.|192\.168\.|169\.254\.|172\.(1[6-9]|2[0-9]|3[01])\.)/.test(h)&&!h.startsWith('[')}catch{return false}};
const sources=(Array.isArray(response.results)?response.results:[]).slice(0,5).filter(r=>isPublic(r.url)&&typeof r.content==='string'&&r.content.length>30&&org&&(`${r.title??''} ${r.content}`).toLowerCase().includes(org)).map(r=>({url:r.url,title:String(r.title??'').slice(0,200),excerpt:r.content.slice(0,1200),retrieved_at:new Date().toISOString()}));
return [{json:{lead_id:lead.id,tender:{title:lead.title,organization:lead.raw_payload?.organization,summary:lead.raw_payload?.summary,requirements:lead.extracted?.requirements??lead.raw_payload?.requirements??[]},sources,search_warning:response.error?'Search provider failed':sources.length?'':'No organization-specific public result'}}];
